import{_ as t,o,c as a,a2 as i}from"./chunks/framework.B0p3fmqd.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"winch/installation.md","filePath":"winch/installation.md","lastUpdated":1791036645000}'),n={name:"winch/installation.md"};function s(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Why</th></tr></thead><tbody><tr><td><code>community_bridge</code></td><td>Framework, notify and target detection</td></tr><tr><td><code>ox_lib</code></td><td>UI helpers</td></tr><tr><td><code>oxmysql</code></td><td>Database</td></tr></tbody></table><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Drop the <code>filthy_winch</code> folder into your resources.</li><li>Add <code>ensure filthy_winch</code> to your server cfg, after the requirements above.</li><li>Add the permission below to your permissions cfg.</li><li>Restart the server.</li></ol><p>There is no SQL file to import and no inventory item to add.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p>The setup menu is locked behind an ace. Admins who hold it get the setup options on the target.</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">add_ace group.admin filthy_winch.admin allow</span></span></code></pre></div><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p>Keybinds are set by each player under Settings, Keybinds, FiveM. Look for the four winch entries.</p><h2 id="setting-up-a-winch" tabindex="-1">Setting up a winch <a class="header-anchor" href="#setting-up-a-winch" aria-label="Permalink to &quot;Setting up a winch&quot;">​</a></h2><p>Every tow truck needs one winch point. That is the spot the rope comes from. You set it once per truck model and it is saved for everyone.</p><ol><li>Sit in or stand next to the truck you want to set up.</li><li>Type <code>/winchsetup</code>.</li><li>Choose <strong>Setup New Winch</strong>.</li><li>Aim at the truck. Move your crosshair to the exact point the rope should come from. The hook end of a tow arm or the middle of the rear bed both work well.</li><li>Left click to capture. Right click cancels.</li><li>The point is saved straight away and every player has it from that moment.</li></ol><p>Choose <strong>Current Winches</strong> in the same menu to see everything you have set up and to delete any of them.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If a truck has no winch point set, the winch will not attach to it. That is the usual reason a new truck does not work. Some vehicles have no collisions at the point you aim at, so try another spot.</p></div><p>Saved points live in <code>shared/winch_custom_trucks.json</code>. You can edit that file by hand, but the menu is easier and works out the offsets for you.</p>',17)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
